-- Airlinerra Fallon Municipal FLX runway 03 and runway 21 Oct 2026 FAA LDA gaps.
-- Source publishes TORA/TODA 5703ft in BOTH directions, but LDA is blank.
-- FAA Chart Supplement Sep03 2026 remains in effect to Oct29 2026.
-- Airport owner City of Fallon is identified but no formal clarification request was sent.
-- WARNING: do not interpret TORA/TODA, 5705ft physical, or 5603ft nominal as official LDA.
INSERT INTO airlinerra.airport_faa_declared_distance_clarifications
(evidence_cycle, airport_key, faa_identifier, runway_pair, runway_end, published_tora_ft, published_toda_ft, published_asda_ft, published_lda_ft, physical_runway_length_ft, displaced_threshold_ft, clarification_status, research_note, source_urls, next_action) VALUES
('2026-10-01', 'OURAIRPORTS:19878', 'FLX', '03/21', '03', 5703, 5703, NULL, NULL, 5705, 102, 'NEEDS_FAA_OR_AIRPORT_OPERATOR_WRITTEN_CLARIFICATION', 'October 2026 governmental BTS NASR runway-end row has TORA/TODA 5703ft but blank LDA for each end of paved 03/21. FAA Chart Supplement Sep03-Oct29 edition corroborates TORA/TODA only, omits LDA. This is a partially declared runway pair: FAA AIM all-blank fallback is not applicable under the strict research screening policy. Displaced threshold of 102ft is specific to RW03. Do not equate TORA, TODA, 5705ft physical runway or 5603ft nominal pavement with source-published LDA. Written source interpretation is not yet requested or received.', ARRAY['https://services.arcgis.com/xOi1kZaI0eWDREZv/arcgis/rest/services/Runway_Ends_Table/FeatureServer/1/query?where=OBJECTID%3D19766&outFields=*&f=json','https://www.faa.gov/air_traffic/flight_info/aeronav/digital_products/dafd/','https://tallyaero.com/atlas/chart-supplement/SW_396/','https://www.fallonnevada.gov/fallon-municipal-airport-flx/','https://www.airnav.com/airport/FLX']::text[], 'Seek documented authoritative FAA Airports/Flight Procedures data clarification or City of Fallon airport-operator response explaining whether airport officially declares LDA for each runway end; record publication cycle, answer and original proof. Do not activate this runway or claim a published LDA meanwhile.'),
('2026-10-01', 'OURAIRPORTS:19878', 'FLX', '03/21', '21', 5703, 5703, NULL, NULL, 5705, NULL, 'NEEDS_FAA_OR_AIRPORT_OPERATOR_WRITTEN_CLARIFICATION', 'October 2026 governmental BTS NASR runway-end row has TORA/TODA 5703ft but blank LDA for each end of paved 03/21. FAA Chart Supplement Sep03-Oct29 edition corroborates TORA/TODA only, omits LDA. This is a partially declared runway pair: FAA AIM all-blank fallback is not applicable under the strict research screening policy. Displaced threshold of 102ft is specific to RW03. Do not equate TORA, TODA, 5705ft physical runway or 5603ft nominal pavement with source-published LDA. Written source interpretation is not yet requested or received.', ARRAY['https://services.arcgis.com/xOi1kZaI0eWDREZv/arcgis/rest/services/Runway_Ends_Table/FeatureServer/1/query?where=OBJECTID%3D19767&outFields=*&f=json','https://www.faa.gov/air_traffic/flight_info/aeronav/digital_products/dafd/','https://tallyaero.com/atlas/chart-supplement/SW_396/','https://www.fallonnevada.gov/fallon-municipal-airport-flx/','https://www.airnav.com/airport/FLX']::text[], 'Seek documented authoritative FAA Airports/Flight Procedures data clarification or City of Fallon airport-operator response explaining whether airport officially declares LDA for each runway end; record publication cycle, answer and original proof. Do not activate this runway or claim a published LDA meanwhile.')
ON CONFLICT (evidence_cycle,airport_key,runway_pair,runway_end) DO NOTHING;

SELECT runway_end,published_tora_ft,published_toda_ft,published_lda_ft,clarification_status,game_admission_status
